const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const crypto = require('node:crypto');
const { buildSync } = require('esbuild');
const root = path.resolve(__dirname, '..');

test('deployed entry cold-starts without local module or JSON files', async () => {
  const source = fs.readFileSync(path.join(root, 'cloudfunctions/peakLifeApi/index.js'), 'utf8');
  const imports = [];
  const query = { where() { return this; }, orderBy() { return this; }, skip() { return this; }, limit() { return this; }, async get() { return { data: [] }; } };
  const context = {
    exports: {},
    require(name) {
      imports.push(name);
      if (name === 'node:crypto') return crypto;
      if (name === 'wx-server-sdk') return {
        DYNAMIC_CURRENT_ENV: 'current', init() {},
        database() { return { collection() { return query; } }; },
        getWXContext() { return { OPENID: 'trusted-owner' }; }
      };
      throw new Error(`Unavailable runtime module: ${name}`);
    }
  };
  vm.runInNewContext(source, context);
  const response = await vm.runInNewContext('exports.main({ action: "listResults", userInfo: { openId: "ignored" }, tcbContext: {} })', context);
  assert.equal(response.ok, true);
  assert.equal(response.apiVersion, '2026-10-15.5');
  assert.equal(response.records.length, 0);
  assert.ok(imports.every(name => ['wx-server-sdk', 'node:crypto'].includes(name)));
});

test('committed cloud entry matches the current source bundle', () => {
  const result = buildSync({
    absWorkingDir: root, entryPoints: ['cloudfunctions/peakLifeApi/main.js'],
    bundle: true, platform: 'node', format: 'cjs', target: 'node16.13',
    external: ['wx-server-sdk'], write: false,
    banner: { js: '// Generated by npm run build:cloud. Edit main.js and lib/, then rebuild.' }
  });
  assert.equal(fs.readFileSync(path.join(root, 'cloudfunctions/peakLifeApi/index.js'), 'utf8').replace(/\r\n/g, '\n'), result.outputFiles[0].text, 'Run npm run build:cloud before deploying');
});
